  public static void Split(Montage m,MediaBlock b,double time){if(time<=b.Start||time>=b.Start+b.Duration)throw new Exception("Choisir une position à l’intérieur du bloc.");double delta=time-b.Start;var right=UiR2.Copy(b);if(!string.IsNullOrEmpty(b.Link941))right.Link941=b.Link941+":cut:"+time.ToString("F6",Engine.Inv);right.Start=time;right.Duration=b.Duration-delta;right.MediaOffset939+=delta;if(right.RawVideoZero.HasValue)right.RawVideoZero+=delta;if(right.RawAudioZero.HasValue)right.RawAudioZero+=delta;b.Duration=delta;b.Fx939=UiR2.Copy(b.Fx939??m.Tracks[b.Track].Fx);right.Fx939=UiR2.Copy(b.Fx939);m.Blocks.Add(right);m.Blocks=m.Blocks.OrderBy(x=>x.Start).ThenBy(x=>x.Track).ToList();}
